import { getPersons } from "../components/apiutils";
import Nav from "../components/Nav";
import {useState,useEffect} from "react";


export default function UserMgmt(){
    const [users, setUsers] = useState([]);
    useEffect(()=>{
        getPersons()
        .then((users)=>{
            setUsers(users)
        })
    },[]);

    return <>
    <Nav>
        <table>
            <thead>
                <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Phone</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                {users.map((user)=>{
                    return <tr>
                        <td>{user.name}</td>
                        <td>{user.email}</td>
                        <td>{user.phoneNumber}</td> 
                    </tr>
                })}
            </tbody>
        </table>
    </Nav>
    </>
}
